/**
 * Logs a page view to the analytics service.
 * Replace the implementation with your actual analytics provider
 * (e.g., Google Analytics, Vercel Analytics, custom endpoint).
 */
export async function logPageView(data: {
  pathname: string;
  userAgent?: string;
  timestamp?: string;
}) {
  const payload = {
    ...data,
    timestamp: data.timestamp ?? new Date().toISOString(),
  };

  const endpoint = process.env.ANALYTICS_ENDPOINT;
  if (endpoint) {
    await fetch(endpoint, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(payload),
    });
  } else {
    // Development fallback: log to console
    console.log("[Analytics] Page view:", payload);
  }
}

